import numpy as np
def read_xyz(fn):
    with open(fn) as f: lines=f.read().splitlines()
    n=int(lines[0]); atoms=[]; coords=[]
    for ln in lines[2:2+n]:
        p=ln.split(); atoms.append(p[0]); coords.append([float(x) for x in p[1:4]])
    return atoms, np.array(coords)
atoms,X = read_xyz('template.xyz')
cov={'H':0.31,'C':0.76,'N':0.71,'P':1.07,'Cl':1.02,'Ge':1.20,'Rh':1.42}
n=len(atoms); bonds=set()
for i in range(n):
    for j in range(i+1,n):
        if np.linalg.norm(X[i]-X[j]) < 1.25*(cov[atoms[i]]+cov[atoms[j]]):
            bonds.add((i,j))
bad=[]
for i in range(n):
    for j in range(i+1,n):
        if (i,j) in bonds: continue
        d=np.linalg.norm(X[i]-X[j])
        thr = 1.5 if (atoms[i]!='H' and atoms[j]!='H') else 1.25
        if d < thr: bad.append((i,atoms[i],j,atoms[j],round(d,2)))
print("nonbonded clashes:", bad)
# key core metrics
Rh,Ge,P,N,ClRh,ClGe1,ClGe2 = 0,1,2,4,3,5,6
cp=[7,9,11,13,15]
def d(i,j): return np.linalg.norm(X[i]-X[j])
print("Rh-Ge %.2f Rh-P %.2f Rh-Cl %.2f Ge-N %.2f N-P %.2f Ge-Cl %.2f %.2f"%(
    d(Rh,Ge),d(Rh,P),d(Rh,ClRh),d(Ge,N),d(N,P),d(Ge,ClGe1),d(Ge,ClGe2)))
print("Rh-Cp:",[round(d(Rh,k),2) for k in cp])
print("Rh-centroid: %.2f"%np.linalg.norm(X[Rh]-X[cp].mean(axis=0)))
print("nbonds:",len(bonds))
